+					fmt.Fprintf(out, "%-20s up to date\n", name)
+				default:
+					fmt.Fprintf(out, "%-20s %s → %s\n", name, o.FromTag, o.ToTag)
+				}
+			}
+			return silencePluginCancel(ctx, firstErr)
+		},
+	}
+	cmd.Flags().BoolVar(&all, "all", false, "Upgrade every remote-installed plugin")
+	return cmd
+}
